INSERT INTO `cms_block` (`title`,`identifier`,`content`,`creation_time`,`update_time`,`is_active`) SELECT 'Course C1245b — Funding And Grant','course_C1245b_funding_and_grant','<p>WSQ funding is only applicable to Singaporeans and PR. Subject to eligibility, the funding support is subjected to funding caps.</p> <table border="1" style="width: 100%;"> <tbody> <tr> <td colspan="5" style="text-align: center;"><strong></strong><strong></strong><strong><span>Effective for courses starting from 1 Jan 2024</span></strong></td> </tr> <tr> <td rowspan="2" style="text-align: center;"><strong>Full Fee</strong></td> <td rowspan="2" style="text-align: center;"><strong>GST</strong></td> <td colspan="3" style="text-align: center;"><strong>Nett Fee after Funding (Incl. GST)</strong></td> </tr> <tr> <td style="text-align: center;"><span><strong>Baseline</strong></span></td> <td style="text-align: center;"><strong>MCES / SME</strong></td> </tr> <tr> <td style="text-align: center;">$720</td> <td style="text-align: center;">$64.80</td> <td style="text-align: center;">$424.80</td> <td style="text-align: center;">$280.80</td> </tr> </tbody> </table> <p>Baseline: Singaporean/PR age 21 and above<br />MCES(Mid-Career Enhanced Subsidy): S''porean age 40 &amp; above</p> <p>Upon registration, we will advise further on how to tap on the WSQ Training Subsidy.</p> <hr /> <p>You can pay the nett fee (a<span>fter the WSQ training subsidy)&nbsp;</span>by the following :</p> <h3>SkillsFuture Enterprise Credit (SFEC)</h3> <p>Eligible Singapore-registered companies can tap on $10000 SFEC to cover up out-of-pocket expenses.<a href="https://sfec.enterprisejobskills.gov.sg/Callbackhandler/Prelogin.aspx" target="_blank"><span style="color: #ff0000; text-decoration-line: underline;">Click here to submit SkillsFuture Enterprise Credit</span></a></p> <h3>SkillsFuture Credit</h3> <p>Eligible Singapore Citizens can use their SkillsFuture Credit to offset course fee payable after funding. <a href="https://www.myskillsfuture.gov.sg/content/portal/en/training-exchange/course-directory/course-detail.html?courseReferenceNumber=TGS-2023019520" title="SkillsFuture Credit" target="_blank"><span style="color: #ff0000; text-decoration-line: underline;">Click here for SkillsFuture Credit submission</span></a></p> <h3>UTAP</h3> <p>Eligible NTUC members can apply for 50% cash rebate of the unfunded fee from UTAP, capped at $250 per year. <a href="https://utap.ntuc.org.sg/onlineClaim" target="_blank"><span style="color: #ff0000; text-decoration-line: underline;">Click here to submit UTAP</span></a></p>',NOW(),NOW(),1 FROM DUAL WHERE @is_sg = 1 AND NOT EXISTS (SELECT 1 FROM `cms_block` WHERE `identifier` = 'course_C1245b_funding_and_grant');
INSERT IGNORE INTO `cms_block_store` (`block_id`,`store_id`) SELECT `block_id`,0 FROM `cms_block` WHERE `identifier` = 'course_C1245b_funding_and_grant';
